Create Fiscal Invoice.code:
// Issue a fiscal receipt for a payment.
// post() adds the /client/ prefix for you.
post('CreateInvoice', {
  // Your own unique invoice reference.
  invoice_id: $.data.paymentReference,
  customerId: $.data.customerId,
  items: [
    {
      description: 'Outpatient consultation',
      quantity: 1,
      unitPrice: 15000,
      taxCode: 'A', // tax group code
    },
  ],
});

Create Invoice From Line Items.code:
// Map an upstream sale's lines into a fiscal receipt.
post('CreateInvoice', {
  invoice_id: $.data.saleId,
  customerId: $.data.customerId,
  items: $.data.lines.map(line => ({
    description: line.productName,
    quantity: line.quantity,
    unitPrice: line.price,
    taxCode: line.taxCode,
  })),
});

Cancel Invoice.code:
// Cancel an invoice issued in error.
post('CancelInvoice', {
  invoice_id: $.data.invoiceId,
});
